pub fn dump_tables(
    out: &mut impl Write,
    path: &str,
    font: &read_fonts::FontRef<'_>,
) -> io::Result<()> {
    use read_fonts::FontRead;
    {
        let path = &format!("{path}.maxp");
        let tag = Tag::new(b"maxp");
        match font
            .table_data(tag)
            .ok_or(ReadError::TableIsMissing(tag))
            .and_then(Maxp::read)
        {
            Ok(table) => dump_Maxp(out, path, &table)?,
            Err(error) => writeln!(out, "{path}.error={}", crate::error(error))?,
        }
    }
    {
        let path = &format!("{path}.MAXP");
        let tag = Tag::new(b"MAXP");
        match font
            .table_data(tag)
            .ok_or(ReadError::TableIsMissing(tag))
            .and_then(MaxpExtended::read)
        {
            Ok(table) => dump_MaxpExtended(out, path, &table)?,
            Err(error) => writeln!(out, "{path}.error={}", crate::error(error))?,
        }
    }
    Ok(())
}
